                    ans.add(i);
            }

            // Calculate hash value for the next window
            if (i < n - m) {
                t = (d * (t - txt.charAt(i) * h)
                     + txt.charAt(i + m))
                    % q;
                if (t < 0)
                    t += q;
            }
        }
        return ans;
    }

